NUM={'2.495':'2,495','1.162':'1,162','1.718':'1,718'}
def tr(src,dst,extra):
    t=open(src).read()
    t=re.sub(r'<style.*?</style>',lambda m:m.group(0).replace('\x00',''),t,flags=re.S)
    # protect style/script
    keep=[]
    def prot(m): keep.append(m.group(0)); return f'\x01{len(keep)-1}\x01'
    t=re.sub(r'<(style|script)[^>]*>.*?</\1>',prot,t,flags=re.S)
    for es in sorted(T,key=len,reverse=True):
        en=T[es]
        t=re.sub(r'>(\s*)'+re.escape(es)+r'(\s*)<',lambda m:'>'+m.group(1)+en+m.group(2)+'<',t)
        t=t.replace('="'+es+'"','="'+en+'"')
    for a,b in NUM.items(): t=t.replace('<b>'+a+'<','<b>'+b+'<')
    for a,b in extra: t=t.replace(a,b)
    t=re.sub(r'\x01(\d+)\x01',lambda m:keep[int(m.group(1))],t)
    os.makedirs(os.path.dirname(dst),exist_ok=True); open(dst,'w').write(t)
    left=[s for s in re.findall(r'>([^<>]*[áéíóúñ¿¡][^<>]*)<',re.sub(r'<(style|script)[^>]*>.*?</\1>','',t,flags=re.S))]
    print(dst,'restos con acentos:',[x.strip()[:60] for x in left if x.strip()][:40])
